<?php require_once "../db.php";require_role("Teacher");$qid=(int)($_GET["quiz_id"]??0);$st=$conn->prepare("SELECT * FROM questions WHERE quiz_id=? ORDER BY id");$st->bind_param("i",$qid);$st->execute();$r=$st->get_result();?>
<!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Manage Questions</title><link href="https://cdn.jsdelivr.net/npm/bootstrap@5.3.3/dist/css/bootstrap.min.css" rel="stylesheet"><link href="../assets/style.css" rel="stylesheet"></head><body><div class="container py-5"><div class="d-flex justify-content-between mb-3"><h2 class="fw-bold">Manage Questions</h2><a href="add_question.php?quiz_id=<?=$qid?>" class="btn btn-primary">+ Add Question</a></div><?php $n=1;while($q=$r->fetch_assoc()):?><div class="card panel-card mb-3"><div class="card-body"><h5><?=$n++?>. <?=e($q["question"])?></h5><div class="row"><div class="col-md-6">A. <?=e($q["option_a"])?></div><div class="col-md-6">B. <?=e($q["option_b"])?></div><div class="col-md-6">C. <?=e($q["option_c"])?></div><div class="col-md-6">D. <?=e($q["option_d"])?></div></div><div class="mt-2"><span class="badge bg-success">Correct: <?=$q["correct_answer"]?></span> <a class="btn btn-sm btn-outline-primary ms-2" href="edit_question.php?id=<?=$q["id"]?>">Edit</a><a class="btn btn-sm btn-outline-danger float-end" href="delete_question.php?id=<?=$q["id"]?>&quiz_id=<?=$qid?>" onclick="return confirm('Delete?')">Delete</a></div></div></div><?php endwhile;?></div></body></html>
